  const layerCount = 21;
  const halfLayers = (layerCount - 1) / 2;
  const rise = 4.77;
  const twist = -0.64 * Math.PI / 180;
  const layers = [];
  let width = 640;
  let height = 610;
  let pixelRatio = 1;
  let elapsed = motionQuery.matches ? 9 : 0;
  let paused = motionQuery.matches;
  let visible = true;
  let frameRequest = 0;
  let lastFrame = 0;
  let paintedAt = 0;
  let yaw = 0;
  let pitch = 0;
